html:
{%- set logo = frappe.db.get_value("Company", doc.company, "company_logos") -%}
{%- set party_label = doc.quotation_to or "Customer" -%}

<style>
  @page { size: A4; margin: 10mm; }
  .qtn { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #000; background: #fff; }
  .qtn table { width: 100%; border-collapse: collapse; }
  .qtn .hdr td { vertical-align: middle; padding: 0; }
  .qtn .logo img { max-height: 70px; max-width: 160px; }
  .qtn .co-name { font-size: 20px; font-weight: bold; text-transform: uppercase; }
  .qtn .co-addr { font-size: 10px; line-height: 1.4; margin-top: 3px; }
  .qtn .title { text-align: center; font-size: 16px; font-weight: bold; letter-spacing: 2px;
                border-top: 2px solid #000; border-bottom: 2px solid #000; padding: 5px 0; margin: 8px 0; }
  .qtn .info td { vertical-align: top; padding: 6px 8px; border: 1px solid #000; width: 50%; }
  .qtn .info .lbl { display: inline-block; min-width: 85px; font-weight: bold; }
  .qtn .items { margin-top: 10px; }
  .qtn .items th { border: 1px solid #000; padding: 5px 4px; background: #fff; font-size: 10.5px; text-transform: uppercase; }
  .qtn .items td { border: 1px solid #000; padding: 4px; vertical-align: middle; }
  .qtn .items thead { display: table-header-group; }
  .qtn .items tr { page-break-inside: avoid; }
  .qtn .r { text-align: right; }
  .qtn .c { text-align: center; }
  .qtn .tot td { padding: 4px 6px; border: 1px solid #000; }
  .qtn .words { margin-top: 6px; font-weight: bold; }
  .qtn .terms { margin-top: 14px; border: 1px solid #000; padding: 6px 8px; page-break-inside: avoid; }
  .qtn .terms h4 { margin: 0 0 4px 0; font-size: 11px; text-transform: uppercase; border-bottom: 1px solid #000; padding-bottom: 3px; }
  .qtn .sign { margin-top: 40px; }
  .qtn .sign td { width: 50%; padding-top: 4px; font-size: 10px; }
  .qtn .sign .line { border-top: 1px solid #000; width: 70%; }
  .qtn svg.barcode { max-width: 110px; height: 34px; }
</style>

<div class="qtn">

  <!-- HEADER: logo + company -->
  <table class="hdr">
    <tr>
      <td class="logo" style="width:25%;">
        {% if logo %}<img src="{{ logo }}" alt="logo">{% endif %}
      </td>
      <td style="width:75%; text-align:right;">
        <div class="co-name">{{ doc.company }}</div>
        {% if doc.company_address_display %}
        <div class="co-addr">{{ doc.company_address_display }}</div>
        {% endif %}
      </td>
    </tr>
  </table>

  <div class="title">QUOTATION</div>

  <!-- PARTY + DOC INFO -->
  <table class="info">
    <tr>
      <td>
        <div><span class="lbl">Party Type</span>: {{ party_label }}</div>
        <div><span class="lbl">{{ party_label }} ID</span>: {{ doc.party_name }}</div>
        <div><span class="lbl">Name</span>: <b>{{ doc.customer_name }}</b></div>
        {% if doc.address_display %}
        <div style="margin-top:4px;"><span class="lbl">Address</span>:</div>
        <div style="line-height:1.4;">{{ doc.address_display }}</div>
        {% endif %}
        {% if doc.contact_display %}
        <div style="margin-top:4px;"><span class="lbl">Contact</span>: {{ doc.contact_display }}</div>
        {% endif %}
      </td>
      <td>
        <div><span class="lbl">Quotation No</span>: <b>{{ doc.name }}</b></div>
        <div><span class="lbl">Date</span>: {{ frappe.format(doc.transaction_date, {'fieldtype': 'Date'}) }}</div>
        {% if doc.valid_till %}
        <div><span class="lbl">Valid Till</span>: {{ frappe.format(doc.valid_till, {'fieldtype': 'Date'}) }}</div>
        {% endif %}
        <div><span class="lbl">Currency</span>: {{ doc.currency }}</div>
        <div><span class="lbl">Order Type</span>: {{ doc.order_type }}</div>
      </td>
    </tr>
  </table>

  <!-- ITEMS -->
  <table class="items">
    <thead>
      <tr>
        <th style="width:4%;">#</th>
        <th style="width:14%;">Item Code</th>
        <th>Item Name</th>
        <th style="width:7%;">UOM</th>
        <th style="width:7%;">Qty</th>
        <th style="width:10%;">Rate</th>
        <th style="width:12%;">Price</th>
        <th style="width:17%;">Barcode</th>
      </tr>
    </thead>
    <tbody>
      {% for row in doc.items %}
      {%- set barcode = frappe.db.get_value("Item Barcode", {"parent": row.item_code}, "barcode") -%}
      <tr>
        <td class="c">{{ loop.index }}</td>
        <td>{{ row.item_code }}</td>
        <td>
          {{ row.item_name }}
          {% if row.description and row.description != row.item_name %}
          <div style="font-size:9.5px;">{{ row.description }}</div>
          {% endif %}
        </td>
        <td class="c">{{ row.uom }}</td>
        <td class="r">{{ row.get_formatted("qty", doc) }}</td>
        <td class="r">{{ row.get_formatted("rate", doc) }}</td>
        <td class="r">{{ row.get_formatted("amount", doc) }}</td>
        <td class="c">
          {% if barcode %}
          {#- data-barcode-value is drawn by Frappe's Desk preview; the script below draws it for /printview and PDF -#}
          <svg class="barcode"
               data-barcode-value="{{ barcode }}"
               data-options='{"format": "CODE128", "height": 28, "width": 1, "fontSize": 10, "margin": 0, "displayValue": true}'></svg>
          {% endif %}
        </td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <!-- TOTALS -->
  <table style="margin-top:8px;">
    <tr>
      <td style="width:55%; vertical-align:top;">
        <div class="words">{{ doc.in_words }}</div>
        <div style="margin-top:4px;">Total Qty: <b>{{ doc.total_qty }}</b></div>
      </td>
      <td style="width:45%;">
        <table class="tot">
          <tr><td>Total</td><td class="r">{{ doc.get_formatted("total") }}</td></tr>
          {% for t in doc.taxes %}
          <tr><td>{{ t.description }}</td><td class="r">{{ t.get_formatted("tax_amount", doc) }}</td></tr>
          {% endfor %}
          {% if doc.discount_amount %}
          <tr><td>Discount</td><td class="r">- {{ doc.get_formatted("discount_amount") }}</td></tr>
          {% endif %}
          <tr><td><b>Grand Total</b></td><td class="r"><b>{{ doc.get_formatted("grand_total") }}</b></td></tr>
        </table>
      </td>
    </tr>
  </table>

  <!-- TERMS -->
  {% if doc.terms %}
  <div class="terms">
    <h4>Terms &amp; Conditions{% if doc.tc_name %} - {{ doc.tc_name }}{% endif %}</h4>
    <div>{{ doc.terms }}</div>
  </div>
  {% endif %}

  <!-- SIGNATURES -->
  <table class="sign">
    <tr>
      <td><div class="line"></div>Customer Signature &amp; Stamp</td>
      <td class="r"><div class="line" style="margin-left:auto;"></div>Authorised Signatory</td>
    </tr>
  </table>

</div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/jsbarcode/3.11.6/JsBarcode.all.min.js"></script>
<script>
  document.querySelectorAll("svg.barcode[data-barcode-value]").forEach(function (el) {
    try { JsBarcode(el, el.dataset.barcodeValue, JSON.parse(el.dataset.options || "{}")); } catch (e) {}
  });
</script>
